import urllib.request
import json
import requests

# Get caffeine information from PubChem
cid = 2519  # Caffeine CID
url = f'https://pubchem.ncbi.nlm.nih.gov/rest/pug/compound/cid/{cid}/JSON'

try:
    response = requests.get(url, headers={'User-Agent': 'Mozilla/5.0'})
    print('Status code:', response.status_code)

    if response.status_code == 200:
        data = response.json()
        print('Caffeine information:')

        # Extract basic info
        compound = data.get('PC_Compounds', [{}])[0]

        # Get name
        for prop in compound.get('props', []):
            if prop.get('urn', {}).get('label') == 'IUPAC Name' or prop.get('urn', {}).get('name') == 'IUPAC Name':
                print('Name:', prop.get('value', {}).get('sval', 'N/A'))
                break

        # Get molecular formula
        atoms = compound.get('atoms', {})
        if atoms:
            elements = atoms.get('element', [])
            print('Number of atoms:', len(elements))

        # Get formula from properties
        for prop in compound.get('props', []):
            if prop.get('urn', {}).get('label') == 'Molecular Formula':
                print('Molecular Formula:', prop.get('value', {}).get('sval', 'N/A'))
                break

        # Get molecular weight
        for prop in compound.get('props', []):
            if prop.get('urn', {}).get('label') == 'Molecular Weight':
                print('Molecular Weight:', prop.get('value', {}).get('fval', 'N/A'))
                break

    else:
        print('Failed to fetch data:', response.text[:200])

except Exception as e:
    print('Error:', str(e))
""}

