import urllib.request
import json
import requests

# Get properties for caffeine metabolites
metabolites = {
    'Paraxanthine': 4687,
    'Theobromine': 5429,
    'Theophylline': 2153
}

for name, cid in metabolites.items():
    url = f'https://pubchem.ncbi.nlm.nih.gov/rest/pug/compound/cid/{cid}/property/MolecularFormula,MolecularWeight/JSON'
    try:
        response = requests.get(url, headers={'User-Agent': 'Mozilla/5.0'})
        if response.status_code == 200:
            data = response.json()
            properties = data.get('PropertyTable', {}).get('Properties', [{}])[0]
            formula = properties.get('MolecularFormula', 'N/A')
            weight = properties.get('MolecularWeight', 'N/A')
            print(f'{name} (CID {cid}): {formula}, MW: {weight}')
        else:
            print(f'{name}: Failed to fetch data')
    except Exception as e:
        print(f'{name}: Error - {str(e)}')
""}

